compile.workshop:
variables {
    global:
        0: g
        1: h
    player:
        0: pv
}

rule ("arrays") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Modify Global Variable(g, Add, 1);
        Modify Global Variable(g, Append To Array, Array(5));
        Modify Global Variable(g, Remove From Array By Value, Array(5));
        Modify Global Variable(g, Remove From Array By Value, Global.h);
        Modify Global Variable(g, Remove From Array By Value, Null);
        Modify Global Variable(g, Append To Array, Global.h);
        Modify Player Variable At Index(Event Player, pv, 0, Multiply, -1);
        Modify Player Variable At Index(Event Player, pv, 1, Add, 2);
        Modify Global Variable At Index(g, 0, Add, 1);
        Set Global Variable(g, Array(1, 2));
        Set Global Variable(g, Array(2, 3));
        Set Global Variable(g, Custom String("b"));
        Set Global Variable(g, 3);
        Set Global Variable(g, Remove From Array(Global.h, 1));
        Set Global Variable(g, Global.h);
        Set Global Variable(g, 62800);
        Set Global Variable(g, String Split(Custom String("7-4"), Custom String("-")));
        Set Global Variable(g, Custom String("8"));
    }
}

